const o=document.getElementById("theme-toggle"),c=document.getElementById("theme-icon-sun"),m=document.getElementById("theme-icon-moon");function n(){const e=document.documentElement.getAttribute("data-theme")==="dark";c.classList.toggle("hidden",!e),m.classList.toggle("hidden",e)}n();o.addEventListener("click",()=>{const t=document.documentElement.getAttribute("data-theme")==="dark"?"light":"dark";document.documentElement.setAttribute("data-theme",t),localStorage.setItem("theme",t),n()});const d=document.getElementById("mobile-menu-btn"),l=document.getElementById("mobile-menu");d.addEventListener("click",()=>{l.classList.toggle("hidden")});
